style.css:
@-moz-document domain("roblox.com") {
/* Hide the real Robux amount */
  #nav-robux-amount {
    visibility: hidden !important;
  }
  /* Show a fake Robux amount in the same place */
  #nav-robux-amount::after {
    content: "999,999" !important;  /* Your fake Robux */
    visibility: visible !important;
    position: absolute;
    color: #fff;  /* Or match Roblox style */
  }
}
